## The C Function

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node *next;
} Node;

Node *reverse_list(Node *head)
{
    Node *prev = NULL;      /* 1 */
    Node *curr = head;      /* 2 */
    Node *next = NULL;      /* 3 */

    while (curr != NULL) {  /* 4 */
        next = curr->next;  /* 5 */
        curr->next = prev;  /* 6 */
        prev = curr;        /* 7 */
        curr = next;        /* 8 */
    }

    return prev;            /* 9 */
}
```

